// ── Feature flag service abstraction ────────────────────────────
class FeatureFlagService {
  constructor(flagStore) {
    this.flagStore = flagStore; // e.g. Redis, LaunchDarkly SDK, DB
  }

  // Consistent user bucketing — same user always gets same experience
  _hashUser(flagKey, userId) {
    // Simple deterministic hash: flag + user → 0-99 bucket
    let hash = 0;
    const seed = `${flagKey}:${userId}`;
    for (const char of seed) {
      hash = (hash * 31 + char.charCodeAt(0)) & 0xffff;
    }
    return hash % 100; // Bucket 0-99
  }

  async isEnabled(flagKey, context = {}) {
    const flag = await this.flagStore.get(flagKey);
    if (!flag || !flag.enabled) return false;

    // Rule 1: specific user allowlist
    if (flag.allowedUsers && context.userId) {
      if (flag.allowedUsers.includes(context.userId)) return true;
    }

    // Rule 2: percentage rollout (consistent hashing)
    if (flag.rolloutPercentage !== undefined && context.userId) {
      const bucket = this._hashUser(flagKey, context.userId);
      return bucket < flag.rolloutPercentage;
    }

    // Rule 3: environment targeting
    if (flag.environments) {
      return flag.environments.includes(process.env.APP_ENV);
    }

    return flag.enabled;
  }
}

// ── Usage in a route handler ─────────────────────────────────────
async function checkoutHandler(req, res) {
  const { user } = req;
  const flags = req.app.get('featureFlags');

  // Dark launch: only internal users see new flow
  const useNewFlow = await flags.isEnabled('new-checkout-flow', {
    userId: user.id
  });

  if (useNewFlow) {
    // New code path: deployed but gated
    return newCheckoutService.process(req.body, user);
  }

  // Legacy code path: unchanged
  return legacyCheckoutService.process(req.body, user);
}

// ── Flag config in the store (JSON) ─────────────────────────────
// {
//   "new-checkout-flow": {
//     "enabled": true,
//     "rolloutPercentage": 10,   // 10% of users get the new flow
//     "allowedUsers": ["user_internal_001", "user_beta_042"]
//   }
// }
//
// Kill switch: set enabled: false → all users see legacy flow
// No deployment required — change propagates within seconds
